    <script>
    (function () {
    const qs = (s, r=document) => r.querySelector(s);

    const lockScroll = (on) => {
        document.documentElement.classList.toggle('no-scroll', on);
        document.body.classList.toggle('no-scroll', on);
    };

    let lastTrigger = null;

    const openModal = (id, triggerEl) => {
        const modal = document.getElementById(id);
        if (!modal) return;

        lastTrigger = triggerEl || null;

        modal.classList.add('is-open');
        modal.setAttribute('aria-hidden', 'false');
        lockScroll(true);

        if (triggerEl) triggerEl.setAttribute('aria-expanded', 'true');

        // фокус в диалог
        const focusTarget =
        qs('.disc-modal__close', modal) ||
        qs('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])', modal);

        if (focusTarget) focusTarget.focus({ preventScroll: true });
    };

    const closeModal = (modal) => {
        if (!modal) return;

        modal.classList.remove('is-open');
        modal.setAttribute('aria-hidden', 'true');
        lockScroll(false);

        const id = modal.id;
        // обновить aria-expanded у всех триггеров этой модалки
        document.querySelectorAll(`[data-modal-open="${CSS.escape(id)}"]`)
        .forEach(btn => btn.setAttribute('aria-expanded', 'false'));

        if (lastTrigger) {
        lastTrigger.focus({ preventScroll: true });
        lastTrigger = null;
        }
    };

    document.addEventListener('click', (e) => {
        const openBtn = e.target.closest('[data-modal-open]');
        if (openBtn) {
        e.preventDefault();
        const id = openBtn.getAttribute('data-modal-open');
        openModal(id, openBtn);
        return;
        }

        const closeBtn = e.target.closest('[data-modal-close]');
        if (closeBtn) {
        e.preventDefault();
        const modal = closeBtn.closest('.disc-modal');
        closeModal(modal);
        }
    });

    document.addEventListener('keydown', (e) => {
        if (e.key !== 'Escape') return;
        const modal = qs('.disc-modal.is-open');
        if (modal) closeModal(modal);
    });
    })();
    </script>

    <script>
document.addEventListener('DOMContentLoaded', () => {
  const items = document.querySelectorAll('.faq__acc');
  if (!items.length) return;

  const openClass = 'is-open';

  function closeItem(item) {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    item.classList.remove(openClass);

    // фиксируем текущую высоту и анимируем в 0
    content.style.height = content.scrollHeight + 'px';
    content.offsetHeight; // reflow
    content.style.height = '0px';
  }

  function openItem(item) {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    item.classList.add(openClass);

    // если было auto — вернем в пиксели перед анимацией
    content.style.height = content.scrollHeight + 'px';

    content.addEventListener('transitionend', function onEnd(e) {
      if (e.propertyName !== 'height') return;
      if (item.classList.contains(openClass)) content.style.height = 'auto';
      content.removeEventListener('transitionend', onEnd);
    });
  }

  // init: поддержка твоего класса faq__acc-content-active
  items.forEach(item => {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    content.style.overflow = 'hidden';
    content.style.transition = 'height 250ms ease';

    const isActive = content.classList.contains('faq__acc-content-active');
    if (isActive) {
      item.classList.add(openClass);
      content.style.height = 'auto';
    } else {
      content.style.height = '0px';
    }
  });

  // click handler: один открыт, остальные закрываем
  items.forEach(item => {
    item.addEventListener('click', (e) => {
      e.preventDefault();

      const isOpen = item.classList.contains(openClass);

      items.forEach(i => { if (i !== item) closeItem(i); });

      if (isOpen) closeItem(item);
      else openItem(item);
    });
  });
});
</script>

